28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
36	
37	export interface ScenarioResult {
38	  results: StepResult[];
39	}
40	
41	const PROCESSING_FEE = 5;
42	const FIRST_INSURANCE_SURCHARGE = 0.1;
43	
44	const BASE_PREMIUMS = {
45	  sword: 100,
46	  amulet: 60,
47	  staff: 80,
48	  potion: 40,
49	  rune: 25,
50	  moonstone: 25,
51	} as const satisfies Record<string, number>;
52	
53	type KnownItemType = keyof typeof BASE_PREMIUMS;
54	
55	const basePremiumOf = (itemType: string): number => BASE_PREMIUMS[itemType as KnownItemType];
56	
57	const BLOCK_SIZE = 3;
58	const BLOCK_PREMIUM = 60;
59	
60	const countsByType = (items: Item[]): Map<string, number> => {
61	  const counts = new Map<string, number>();
62	  for (const item of items) counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
63	  return counts;
64	};
65	
66	const basePremiumForGroup = (itemType: string, count: number): number => {
67	  if (count === BLOCK_SIZE) return BLOCK_PREMIUM;
68	  return count * basePremiumOf(itemType);
69	};
70	
71	const policyBasePremiumOf = (items: Item[]): number =>
72	  [...countsByType(items)].reduce(
73	    (total, [itemType, count]) => total + basePremiumForGroup(itemType, count),
74	    0,
75	  );
76	
77	const CURSE_SURCHARGE = 0.5;
78	
79	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
80	const HIGH_ENCHANTMENT_THRESHOLD = 5;
81	
82	const surchargeRateFor = (item: Item): number => {
83	  const curse = item.cursed ? CURSE_SURCHARGE : 0;
84	  const enchantment =
85	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD ? HIGH_ENCHANTMENT_SURCHARGE : 0;
86	  return curse + enchantment;
87	};
88	
89	const itemSurchargesOf = (items: Item[]): number =>
90	  items.reduce((total, item) => total + basePremiumOf(item.type) * surchargeRateFor(item), 0);
91	
92	const LOYALTY_DISCOUNT = 0.2;
93	const LOYALTY_THRESHOLD_YEARS = 2;
94	
95	const policyModifierRateOf = (customer: Customer): number => {
96	  const loyalty = customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS ? -LOYALTY_DISCOUNT : 0;
97	  return FIRST_INSURANCE_SURCHARGE + loyalty;
98	};
99	
100	const premiumFor = (quote: QuoteStep, customer: Customer): number => {
101	  const policyBase = policyBasePremiumOf(quote.items);
102	  // Policy-scoped modifiers apply to the policy base only; item-scoped
103	  // surcharges are added afterwards and never widen that base.
104	  const policyModifiers = policyBase * policyModifierRateOf(customer);
105	  return Math.ceil(
106	    policyBase + itemSurchargesOf(quote.items) + policyModifiers + PROCESSING_FEE,
107	  );
108	};
109	
110	const resultOf = (step: Step, customer: Customer): StepResult => {
111	  if (step.op === "quote") return { premium: premiumFor(step, customer) };
112	  throw new Error(`unsupported step: ${step.op}`);
113	};
114	
115	export const runScenario = (scenario: Scenario): ScenarioResult => ({
116	  results: scenario.steps.map((step) => resultOf(step, scenario.customer)),
117	});
