// Customer-derived share of the policy-scoped rate. Other policy-scoped
// modifiers (e.g. the follow-up contract discount, which depends on a step's
// position in the scenario rather than on the customer) belong alongside this
// one, not inside it.
const customerModifierRateOf = (customer: Customer): number => {
  const loyalty = customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS ? -LOYALTY_DISCOUNT : 0;
  return FIRST_INSURANCE_SURCHARGE + loyalty;
};
